const items = $input.all();
return items.map(() => {
  // NOTE: $json here is the passcode-hash lookup row, not the original
  // webhook payload — reference $('Webhook') explicitly for the request body.
  const body = ($('Webhook').first().json && $('Webhook').first().json.body) || {};

  // --- view ---
  // Role comes from Resolve Role (server-side passcode match). The client
  // role is analytics-only; lexicon + corrections are operator territory.
  const role = ($('Resolve Role').first().json || {}).role || '';
  const OPERATOR_ONLY = ['lexicon', 'lexiconSave', 'corrections'];

  const validViews = ['log', 'overview', 'lexicon', 'lexiconSave', 'corrections'];
  let view = validViews.includes(body.view) ? body.view : 'overview';
  if (OPERATOR_ONLY.includes(view) && role !== 'operator') view = 'forbidden';

  // --- overview: range -> [rangeStartIso, rangeEndIso] ---
  const rangeDaysMap = { '7d': 7, '30d': 30, '90d': 90 };
  const range = ['7d', '30d', '90d', 'all'].includes(body.range) ? body.range : '30d';
  const nowMs = Date.now();
  const rangeEndIso = new Date(nowMs).toISOString();
  const rangeStartIso = range === 'all'
    ? '1970-01-01T00:00:00.000Z'
    : new Date(nowMs - rangeDaysMap[range] * 24 * 60 * 60 * 1000).toISOString();

  // --- log: search / filter / page / pageSize ---
  const search = typeof body.search === 'string' ? body.search : '';
  const validFilters = ['all', 'unknown', 'voice', 'text', 'cache_hit', 'fresh'];
  const filterVal = validFilters.includes(body.filter) ? body.filter : 'all';

  let page = parseInt(body.page, 10);
  if (!Number.isFinite(page) || page < 1) page = 1;

  let pageSize = parseInt(body.pageSize, 10);
  if (!Number.isFinite(pageSize) || pageSize < 1) pageSize = 50;
  if (pageSize > 200) pageSize = 200; // guard against abuse

  const offset = (page - 1) * pageSize;

  return {
    json: {
      view,
      role,
      range,
      rangeStartIso,
      rangeEndIso,
      search,
      filterVal,
      page,
      pageSize,
      offset,
    },
  };
});

// The Postgres node returns one row with a single "result" column
// holding the whole JSON payload we built with json_build_object().
const first = $input.first();
const result = (first && first.json && first.json.result) || {};
return [{ json: result }];

// The Postgres node returns one row with a single "result" column
// holding the whole JSON payload we built with json_build_object().
const first = $input.first();
const result = (first && first.json && first.json.result) || {};
// The UI picks its tabs from this; the server has already refused
// operator-only views for a client passcode.
result.role = ($('Resolve Role').first().json || {}).role || 'client';
return [{ json: result }];

// Tolerate a missing/malformed row: return a valid empty-lexicon
// skeleton instead of erroring, so the editor always has something
// to render even before the key has ever been written.
const first = $input.first();
const raw = first && first.json && first.json.value;
const skeleton = {
  version: 1,
  updatedAt: new Date(0).toISOString(),
  thresholds: { autoApply: 0.86, clarify: 0.72, gap: 0.08, minFuzzyLen: 5 },
  stoplist: [],
  terms: [],
};
if (!raw) return [{ json: skeleton }];
try {
  const parsed = JSON.parse(raw);
  if (!parsed || typeof parsed !== 'object' || !Array.isArray(parsed.terms)) {
    return [{ json: skeleton }];
  }
  return [{ json: parsed }];
} catch (e) {
  return [{ json: skeleton }];
}

// Server-side validation is authoritative — never trust the submitted blob.
const body = ($('Webhook').first().json && $('Webhook').first().json.body) || {};
const input = body.lexicon;

function fail(message) {
  return [{ json: { ok: false, message } }];
}

if (!input || typeof input !== 'object' || Array.isArray(input)) {
  return fail('lexicon must be a JSON object.');
}

const rawSize = Buffer.byteLength(JSON.stringify(input), 'utf8');
if (rawSize > 131072) {
  return fail(`lexicon payload is ${rawSize} bytes, exceeding the 128KB limit.`);
}

if (!Array.isArray(input.terms)) {
  return fail('lexicon.terms must be an array.');
}

const th = input.thresholds;
if (!th || typeof th !== 'object') {
  return fail('lexicon.thresholds must be an object.');
}
const { autoApply, clarify, gap, minFuzzyLen } = th;
if (typeof autoApply !== 'number' || !(autoApply > 0 && autoApply <= 1)) {
  return fail('thresholds.autoApply must be a number in (0, 1].');
}
if (typeof clarify !== 'number' || !(clarify > 0 && clarify <= 1)) {
  return fail('thresholds.clarify must be a number in (0, 1].');
}
if (!(autoApply > clarify)) {
  return fail('thresholds.autoApply must be greater than thresholds.clarify.');
}
if (typeof gap !== 'number' || !(gap >= 0 && gap <= 1)) {
  return fail('thresholds.gap must be a number in [0, 1].');
}
if (!Number.isInteger(minFuzzyLen) || minFuzzyLen < 3) {
  return fail('thresholds.minFuzzyLen must be an integer >= 3.');
}

let stoplist = input.stoplist;
if (stoplist === undefined) stoplist = [];
if (!Array.isArray(stoplist) || !stoplist.every((s) => typeof s === 'string')) {
  return fail('lexicon.stoplist must be an array of strings.');
}

const seenCanonical = new Map(); // lowercased canonical -> original
const seenAlias = new Map(); // lowercased alias -> owning canonical
const cleanTerms = [];

for (let i = 0; i < input.terms.length; i++) {
  const t = input.terms[i];
  const label = `term #${i + 1}`;
  if (!t || typeof t !== 'object' || Array.isArray(t)) {
    return fail(`${label} must be an object.`);
  }
  if (typeof t.canonical !== 'string' || !t.canonical.trim()) {
    return fail(`${label}: canonical must be a non-empty string.`);
  }
  const canonical = t.canonical.trim();
  const canonKey = canonical.toLowerCase();
  if (seenCanonical.has(canonKey)) {
    return fail(`Duplicate canonical term "${canonical}" (also used by "${seenCanonical.get(canonKey)}").`);
  }
  if (!Array.isArray(t.aliases)) {
    return fail(`Term "${canonical}": aliases must be an array.`);
  }
  const aliases = [];
  for (const a of t.aliases) {
    if (typeof a !== 'string' || !a.trim()) {
      return fail(`Term "${canonical}": every alias must be a non-empty string.`);
    }
    const alias = a.trim();
    const aliasKey = alias.toLowerCase();
    const owner = seenAlias.get(aliasKey);
    if (owner && owner !== canonical) {
      return fail(`Alias "${alias}" is claimed by both "${owner}" and "${canonical}" — aliases must be unique across all terms.`);
    }
    seenAlias.set(aliasKey, canonical);
    aliases.push(alias);
  }
  if (typeof t.fuzzy !== 'boolean') {
    return fail(`Term "${canonical}": fuzzy must be a boolean.`);
  }
  seenCanonical.set(canonKey, canonical);
  cleanTerms.push({ canonical, aliases, fuzzy: t.fuzzy });
}

const finalLexicon = {
  version: Number.isInteger(input.version) && input.version > 0 ? input.version : 1,
  updatedAt: new Date().toISOString(), // stamped server-side; client value ignored
  thresholds: { autoApply, clarify, gap, minFuzzyLen },
  stoplist,
  terms: cleanTerms,
};

return [{ json: { ok: true, lexicon: finalLexicon, serialized: JSON.stringify(finalLexicon) } }];

// The Postgres node returns one row with a single "result" column
// holding the whole JSON payload we built with json_build_object().
const first = $input.first();
const result = (first && first.json && first.json.result) || { topPairs: [], clarifications: [] };
return [{ json: result }];
